/* ===== GreenBean Coffee — Global Styles ===== */
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=Playfair+Display:wght@500;600;700&display=swap');

:root {
  --green: #00824A;
  --green-dark: #006B3D;
  --forest: #32462F;
  --cream: #F3CEA1;
  --cream-light: #FDF6EC;
  --cream-pale: #FFFAF3;
  --brown: #5C3D2E;
  --brown-light: #8B6F4E;
  --white: #FFFFFF;
  --gray-50: #FAFAF9;
  --gray-100: #F5F5F4;
  --gray-200: #E7E5E4;
  --gray-300: #D6D3D1;
  --gray-400: #A8A29E;
  --gray-500: #78716C;
  --gray-600: #57534E;
  --gray-700: #44403C;
  --gray-800: #292524;
  --gray-900: #1C1917;
  --font-body: 'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-heading: 'Playfair Display', Georgia, serif;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 10px 30px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 50px rgba(0,0,0,0.12);
  --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-body);
  color: var(--gray-800);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }
a { text-decoration: none; color: inherit; transition: color var(--transition); }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul, ol { list-style: none; }

.container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.container-wide { width: 100%; max-width: 1400px; margin: 0 auto; padding: 0 24px; }

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 28px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.938rem;
  letter-spacing: 0.01em;
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-primary {
  background: var(--green);
  color: var(--white);
}
.btn-primary:hover { background: var(--green-dark); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-outline {
  border: 2px solid var(--green);
  color: var(--green);
  background: transparent;
}
.btn-outline:hover { background: var(--green); color: var(--white); }
.btn-white {
  background: var(--white);
  color: var(--green);
}
.btn-white:hover { background: var(--cream-light); transform: translateY(-1px); }
.btn-dark {
  background: var(--forest);
  color: var(--white);
}
.btn-dark:hover { background: var(--gray-800); }
.btn-sm { padding: 8px 20px; font-size: 0.875rem; }
.btn-lg { padding: 16px 36px; font-size: 1.063rem; }

/* ===== Header ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--white);
  box-shadow: 0 1px 0 var(--gray-200);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--green);
}
.logo-icon {
  width: 40px;
  height: 40px;
  background: var(--green);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.25rem;
}
.nav-main { display: flex; align-items: center; gap: 32px; }
.nav-main a {
  font-weight: 500;
  font-size: 0.938rem;
  color: var(--gray-700);
  padding: 4px 0;
  position: relative;
}
.nav-main a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--green);
  transition: width var(--transition);
}
.nav-main a:hover { color: var(--green); }
.nav-main a:hover::after { width: 100%; }
.nav-main a.active { color: var(--green); }
.nav-main a.active::after { width: 100%; }
.nav-actions { display: flex; align-items: center; gap: 12px; }
.mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}
.mobile-toggle span {
  width: 22px;
  height: 2px;
  background: var(--gray-700);
  border-radius: 2px;
  transition: var(--transition);
}
.mobile-nav {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  z-index: 999;
  padding: 24px;
  flex-direction: column;
  gap: 8px;
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  padding: 14px 0;
  font-size: 1.125rem;
  font-weight: 500;
  border-bottom: 1px solid var(--gray-100);
}
.mobile-nav .nav-actions-mobile {
  display: flex;
  gap: 12px;
  margin-top: 24px;
}

/* ===== Hero ===== */
.hero {
  position: relative;
  min-height: 540px;
  display: flex;
  align-items: center;
  overflow: hidden;
}
.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--forest) 0%, #1a3a1a 50%, var(--green-dark) 100%);
}
.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(0,130,74,0.3) 0%, transparent 70%);
}
.hero-pattern {
  position: absolute;
  inset: 0;
  opacity: 0.05;
  background-image: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='%23ffffff' fill-opacity='1'%3E%3Ccircle cx='30' cy='30' r='4'/%3E%3C/g%3E%3C/svg%3E");
}
.hero-content {
  position: relative;
  z-index: 2;
  color: var(--white);
  max-width: 560px;
}
.hero h1 {
  font-family: var(--font-heading);
  font-size: 3.5rem;
  font-weight: 700;
  line-height: 1.15;
  margin-bottom: 24px;
}
.hero p {
  font-size: 1.188rem;
  opacity: 0.9;
  margin-bottom: 32px;
  line-height: 1.7;
}
.hero-image {
  position: absolute;
  right: 5%;
  top: 50%;
  transform: translateY(-50%);
  width: 420px;
  height: 420px;
  border-radius: 50%;
  background: radial-gradient(circle, var(--cream) 0%, var(--cream-light) 60%, transparent 70%);
  opacity: 0.2;
}

/* ===== Section Styles ===== */
.section { padding: 80px 0; }
.section-sm { padding: 48px 0; }
.section-lg { padding: 100px 0; }
.section-cream { background: var(--cream-pale); }
.section-green { background: var(--green); color: var(--white); }
.section-forest { background: var(--forest); color: var(--white); }

.section-header {
  text-align: center;
  margin-bottom: 48px;
}
.section-header h2 {
  font-family: var(--font-heading);
  font-size: 2.25rem;
  font-weight: 600;
  margin-bottom: 16px;
  color: var(--forest);
}
.section-header p {
  font-size: 1.063rem;
  color: var(--gray-600);
  max-width: 600px;
  margin: 0 auto;
}
.section-green .section-header h2,
.section-forest .section-header h2 { color: var(--white); }
.section-green .section-header p,
.section-forest .section-header p { color: rgba(255,255,255,0.85); }

/* ===== Promo Cards ===== */
.promo-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}
.promo-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  min-height: 380px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 40px;
  transition: transform var(--transition), box-shadow var(--transition);
}
.promo-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); }
.promo-card-green {
  background: linear-gradient(145deg, var(--green) 0%, var(--green-dark) 100%);
  color: var(--white);
}
.promo-card-cream {
  background: linear-gradient(145deg, var(--cream) 0%, var(--cream-light) 100%);
  color: var(--forest);
}
.promo-card-forest {
  background: linear-gradient(145deg, var(--forest) 0%, #1a3a1a 100%);
  color: var(--white);
}
.promo-card-warm {
  background: linear-gradient(145deg, #E8D5B7 0%, var(--cream-light) 100%);
  color: var(--forest);
}
.promo-card h3 {
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 600;
  margin-bottom: 12px;
  line-height: 1.25;
}
.promo-card p {
  font-size: 0.938rem;
  margin-bottom: 24px;
  opacity: 0.9;
  line-height: 1.6;
  max-width: 420px;
}
.promo-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}
.promo-full {
  grid-column: 1 / -1;
}

/* ===== Featured Product ===== */
.featured {
  background: linear-gradient(135deg, var(--cream-pale) 0%, var(--cream-light) 100%);
}
.featured-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.featured-text h2 {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 600;
  color: var(--forest);
  margin-bottom: 20px;
  line-height: 1.2;
}
.featured-text p {
  font-size: 1.063rem;
  color: var(--gray-600);
  margin-bottom: 32px;
  line-height: 1.7;
}
.featured-image {
  aspect-ratio: 4/3;
  border-radius: var(--radius-xl);
  background: linear-gradient(135deg, var(--cream) 0%, #E8C97A 50%, #D4A962 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.featured-image-placeholder {
  font-size: 4rem;
  opacity: 0.5;
}

/* ===== Footer ===== */
.footer {
  background: var(--forest);
  color: var(--white);
  padding: 64px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}
.footer-col h4 {
  font-size: 0.813rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 20px;
  color: var(--cream);
}
.footer-col a {
  display: block;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.7);
  padding: 5px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 32px;
  border-top: 1px solid rgba(255,255,255,0.15);
}
.footer-bottom p {
  font-size: 0.813rem;
  color: rgba(255,255,255,0.5);
}
.footer-social { display: flex; gap: 16px; }
.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  color: rgba(255,255,255,0.7);
  transition: all var(--transition);
}
.footer-social a:hover { background: var(--green); color: var(--white); }
.footer-accordion-toggle {
  display: none;
  width: 100%;
  text-align: left;
  padding: 16px 0;
  font-size: 0.813rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--cream);
  border-bottom: 1px solid rgba(255,255,255,0.1);
  position: relative;
}
.footer-accordion-toggle::after {
  content: '+';
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  font-size: 1.25rem;
  font-weight: 300;
  transition: transform var(--transition);
}
.footer-accordion-toggle.active::after {
  content: '\2212';
}

/* ===== Cookie Banner ===== */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  box-shadow: 0 -4px 20px rgba(0,0,0,0.12);
  z-index: 2000;
  padding: 20px 0;
  transform: translateY(0);
  transition: transform 0.4s ease;
}
.cookie-banner.hidden { transform: translateY(100%); pointer-events: none; }
.cookie-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.cookie-text h4 { font-size: 0.938rem; font-weight: 600; margin-bottom: 4px; }
.cookie-text p { font-size: 0.813rem; color: var(--gray-500); }
.cookie-actions { display: flex; gap: 12px; flex-shrink: 0; }

/* ===== Rewards Page ===== */
.rewards-hero {
  background: linear-gradient(135deg, var(--green) 0%, var(--forest) 100%);
  color: var(--white);
  padding: 80px 0;
  text-align: center;
}
.rewards-hero h1 {
  font-family: var(--font-heading);
  font-size: 3rem;
  margin-bottom: 16px;
}
.rewards-hero p {
  font-size: 1.125rem;
  opacity: 0.9;
  max-width: 560px;
  margin: 0 auto 32px;
}

.how-it-works-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 40px;
}
.how-step {
  text-align: center;
  padding: 40px 24px;
}
.how-step-num {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--green);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  font-weight: 700;
  margin: 0 auto 20px;
}
.how-step h3 {
  font-family: var(--font-heading);
  font-size: 1.375rem;
  margin-bottom: 12px;
  color: var(--forest);
}
.how-step p {
  font-size: 0.938rem;
  color: var(--gray-600);
  line-height: 1.6;
}

/* Tiers */
.tiers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}
.tier-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  transition: transform var(--transition), box-shadow var(--transition);
}
.tier-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); }
.tier-header {
  padding: 32px 28px;
  text-align: center;
}
.tier-green .tier-header { background: var(--green); color: var(--white); }
.tier-gold .tier-header { background: linear-gradient(135deg, #C6952B, #E0B44C); color: var(--white); }
.tier-reserve .tier-header { background: linear-gradient(135deg, var(--forest), #1a3a1a); color: var(--white); }
.tier-header h3 {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  margin-bottom: 6px;
}
.tier-header .tier-threshold { font-size: 0.875rem; opacity: 0.85; }
.tier-benefits {
  padding: 28px;
  background: var(--white);
}
.tier-benefits li {
  padding: 10px 0;
  font-size: 0.875rem;
  color: var(--gray-700);
  border-bottom: 1px solid var(--gray-100);
  display: flex;
  align-items: flex-start;
  gap: 10px;
}
.tier-benefits li:last-child { border-bottom: none; }
.tier-check {
  color: var(--green);
  font-weight: 700;
  flex-shrink: 0;
  margin-top: 2px;
}

/* Redemption Tabs */
.redemption-tabs {
  display: flex;
  gap: 4px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 32px;
  background: var(--gray-100);
  border-radius: var(--radius-full);
  padding: 4px;
  max-width: 720px;
  margin-left: auto;
  margin-right: auto;
}
.redemption-tab {
  padding: 10px 20px;
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-600);
  transition: all var(--transition);
}
.redemption-tab:hover { color: var(--forest); }
.redemption-tab.active {
  background: var(--green);
  color: var(--white);
  box-shadow: var(--shadow-sm);
}
.redemption-content {
  max-width: 600px;
  margin: 0 auto;
  text-align: center;
}
.redemption-panel {
  display: none;
  padding: 40px;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  animation: fadeUp 0.3s ease;
}
.redemption-panel.active { display: block; }
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
.redemption-panel .stars-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--cream);
  color: var(--brown);
  padding: 8px 20px;
  border-radius: var(--radius-full);
  font-weight: 700;
  font-size: 1.125rem;
  margin-bottom: 20px;
}
.redemption-panel h3 {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  color: var(--forest);
  margin-bottom: 12px;
}
.redemption-panel p {
  color: var(--gray-600);
  font-size: 0.938rem;
  line-height: 1.6;
}
.redemption-value {
  display: inline-block;
  margin-top: 16px;
  font-size: 0.813rem;
  color: var(--gray-400);
  font-weight: 500;
}

/* Partnerships */
.partnerships-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}
.partnership-card {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
  transition: box-shadow var(--transition);
}
.partnership-card:hover { box-shadow: var(--shadow-md); }
.partnership-logo {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-md);
  background: var(--cream-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.75rem;
  color: var(--brown);
  flex-shrink: 0;
}
.partnership-card p {
  font-size: 0.938rem;
  color: var(--gray-600);
  line-height: 1.5;
}

/* ===== Menu Page ===== */
.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 48px;
  align-items: flex-start;
}
.menu-sidebar {
  position: sticky;
  top: 96px;
}
.menu-sidebar-section { margin-bottom: 28px; }
.menu-sidebar-section h4 {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-400);
  margin-bottom: 12px;
  padding-left: 12px;
}
.menu-sidebar a {
  display: block;
  padding: 8px 12px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--gray-600);
  border-radius: var(--radius-sm);
  transition: all var(--transition);
}
.menu-sidebar a:hover {
  background: var(--cream-light);
  color: var(--forest);
}
.menu-sidebar a.active {
  background: var(--green);
  color: var(--white);
}
.breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.813rem;
  color: var(--gray-400);
  padding: 16px 0;
}
.breadcrumb a { color: var(--green); }
.breadcrumb span { color: var(--gray-300); }

.menu-section { margin-bottom: 48px; }
.menu-section h2 {
  font-family: var(--font-heading);
  font-size: 1.75rem;
  color: var(--forest);
  margin-bottom: 8px;
}
.menu-section-desc {
  font-size: 0.938rem;
  color: var(--gray-500);
  margin-bottom: 24px;
}
.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 20px;
}
.menu-item {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--white);
  border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.menu-item:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--green);
  transform: translateY(-2px);
}
.menu-item-image {
  aspect-ratio: 1;
  background: var(--cream-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}
.menu-item-info {
  padding: 14px;
}
.menu-item-info h4 {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--forest);
  margin-bottom: 4px;
}
.menu-item-info p {
  font-size: 0.75rem;
  color: var(--gray-400);
}

